window.__OPENSTAX_PHYSICS__[4] = {"schemaVersion":"4.0.0-physics","generatedAt":"2026-11-27T01:33:30.630Z","number":4,"code":"ch04","slug":"forces-and-newton-s-laws-of-motion","title":"Forces and Newton’s Laws of Motion","titleVi":"Lực & Các Định Luật Newton (Forces & Newton’s Laws)","sections":[{"uid":"hsphys.ch04.sec00","moduleId":"m54144","number":"4.0","slug":"introduction","title":"Introduction","isIntroduction":true,"learningObjectives":[],"bilingualGuide":null,"keyEquations":[],"subsections":[{"uid":"hsphys.ch04.sec00.sub01","title":"Chapter Introduction","summaryVi":null,"paragraphs":["Isaac Newton (1642–1727) was a natural philosopher; a great thinker who combined science and philosophy to try to explain the workings of nature on Earth and in the universe. His laws of motion were just one part of the monumental work that has made him legendary. The development of Newton’s laws marks the transition from the Renaissance period of history to the modern era. This transition was characterized by a revolutionary change in the way people thought about the physical universe. Drawing upon earlier work by scientists Galileo Galilei and Johannes Kepler , Newton’s laws of motion allowed motion on Earth and in space to be predicted mathematically. In this chapter you will learn about force as well as Newton’s first, second, and third laws of motion."],"figures":[{"sourceId":"fs-idp25920288","filename":"CNX_HSPhysics_04_00_dolphin.jpg","relativePath":"media/CNX_HSPhysics_04_00_dolphin.jpg","alt":"A dolphin is jumping out of water in a curved path over the water."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":[],"glossary":[],"assessments":[],"stats":{"learningObjectiveCount":0,"keyEquationCount":0,"subsectionCount":1,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":0,"assessmentCount":0}},{"uid":"hsphys.ch04.sec01","moduleId":"m54135","number":"4.1","slug":"force","title":"Force","isIntroduction":false,"learningObjectives":["Differentiate between force, net force, and dynamics","Draw a free-body diagram"],"bilingualGuide":{"notebookSummaryVi":"Khái niệm Lực (Force — đại lượng vectơ, đơn vị N) và kỹ năng vẽ Sơ đồ lực (Free-Body Diagram — FBD).","wordProblemCues":[{"phraseEn":"free-body diagram / net force","meaningVi":"Sơ đồ lực / Hợp lực","mathNotation":"F_net = ΣF"}],"commonTrapsVi":["Chỉ vẽ các lực TÁC DỤNG LÊN vật đang xét, không vẽ lực do vật tác dụng lên vật khác!"]},"keyEquations":[],"subsections":[{"uid":"hsphys.ch04.sec01.sub01","title":"Defining Force and Dynamics","summaryVi":null,"paragraphs":["Force is the cause of motion, and motion draws our attention. Motion itself can be beautiful, such as a dolphin jumping out of the water, the flight of a bird, or the orbit of a satellite. The study of motion is called kinematics , but kinematics describes only the way objects move—their velocity and their acceleration . Dynamics considers the forces that affect the motion of moving objects and systems . Newton’s laws of motion are the foundation of dynamics. These laws describe the way objects speed up, slow down, stay in motion, and interact with other objects. They are also universal laws : they apply everywhere on Earth as well as in space.","A force pushes or pulls an object. The object being moved by a force could be an inanimate object, a table, or an animate object, a person. The pushing or pulling may be done by a person, or even the gravitational pull of Earth. Forces have different magnitudes and directions; this means that some forces are stronger than others and can act in different directions. For example, a cannon exerts a strong force on the cannonball that is launched into the air. In contrast, a mosquito landing on your arm exerts only a small force on your arm.","When multiple forces act on an object, the forces combine. Adding together all of the forces acting on an object gives the total force, or net force . An external force is a force that acts on an object within the system from outside the system. This type of force is different than an internal force, which acts between two objects that are both within the system. The net external force combines these two definitions; it is the total combined external force. We discuss further details about net force, external force, and net external force in the coming sections.","Like displacements, velocities, and accelerations, forces are vectors that have magnitude and direction. We may represent a force as the sum of two vectors at right angles. These are its one-dimensional components, which we can represent by a signed scalar quantity. When we do so, we must choose a coordinate system and the direction along each axis that will be the positive direction. This choice must be the same for all vectors in the problem—forces, accelerations, etc.","Commonly, in a problem set in a vertical plane, horizontal and vertical axes are chosen as the two primary directions. The usual convention is to make the positive directions right and up. Sometimes a problem concerns a sloping plane, and it may be more convenient to choose axes parallel to the plane and normal to it. In this case, it is usual to take positive in each axis as the directions that tend upward.","Thus, a horizontal force of –3 N means pushing with 3 N to the left.","Unknown values are taken to be in the positive direction, so if your calculation of a vertical force comes out as +5.2 N, then you know it is an upward force. A negative result means the force is downward."],"figures":[],"tables":[]},{"uid":"hsphys.ch04.sec01.sub02","title":"Free-Body Diagrams and Examples of Forces","summaryVi":null,"paragraphs":["For our first example of force, consider an object hanging from a rope. This example gives us the opportunity to introduce a useful tool known as a free-body diagram . A free-body diagram represents the object being acted upon—that is, the free body—as a single point. Only the forces acting on the body (that is, external forces) are shown and are represented by vectors (which are drawn as arrows). These forces are the only ones shown because only external forces acting on the body affect its motion. We can ignore any internal forces within the body because they cancel each other out, as explained in the section on Newton’s third law of motion. Free-body diagrams are very useful for analyzing forces acting on an object.","[Figure 4.1] shows the force of tension in the rope acting in the upward direction, opposite the force of gravity. The forces are indicated in the free-body diagram by an arrow pointing up, representing tension, and another arrow pointing down, representing gravity. In a free-body diagram, the lengths of the arrows show the relative magnitude (or strength) of the forces. Because forces are vectors, they add just like other vectors. Notice that the two arrows have equal lengths in [Figure 4.1], which means that the forces of tension and weight are of equal magnitude. Because these forces of equal magnitude act in opposite directions, they are perfectly balanced, so they add together to give a net force of zero.","Not all forces are as noticeable as when you push or pull on an object. Some forces act without physical contact, such as the pull of a magnet (in the case of magnetic force) or the gravitational pull of Earth (in the case of gravitational force).","In the next three sections discussing Newton’s laws of motion, we will learn about three specific types of forces: friction, the normal force , and the gravitational force . To analyze situations involving forces, we will create free-body diagrams to organize the framework of the mathematics for each individual situation."],"figures":[{"sourceId":"fs-idm13112864","filename":"CNX_HSPhysics_04_01_tension.jpg","relativePath":"media/CNX_HSPhysics_04_01_tension.jpg","alt":"An object labeled m for mass is attached to a rope. A force vector labeled T for tension is pointing upward from the object and a force vector labeled W for weight of the object is pointing downward from the object. A free body diagram illustrates the T and W force vectors."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch04.sec01.feat01","type":"tip","title":"Tips for Success","text":"Correctly drawing and labeling a free-body diagram is an important first step for solving a problem. It will help you visualize the problem and correctly apply the mathematics to solve the problem.","images":[]}],"summaryPoints":["Dynamics is the study of how forces affect the motion of objects and systems.","Force is a push or pull that can be defined in terms of various standards. It is a vector and so has both magnitude and direction.","External forces are any forces outside of a body that act on the body. A free-body diagram is a drawing of all external forces acting on a body."],"glossary":[{"term":"dynamics","termVi":"Động lực học","definition":"the study of how forces affect the motion of objects and systems","definitionVi":"Ngành Cơ học nghiên cứu nguyên nhân gây ra hoặc làm thay đổi chuyển động — tức là LỰC (Forces).","memoryTipVi":"Kinematics mô tả chuyển động, còn Dynamics giải thích LỰC gây ra chuyển động."},{"term":"external force","termVi":"Ngoại lực","definition":"a force acting on an object or system that originates outside of the object or system","definitionVi":"Lực do các vật bên ngoài hệ tác dụng lên hệ đang xét.","memoryTipVi":"Chỉ ngoại lực mới làm thay đổi chuyển động của cả hệ."},{"term":"force","termVi":"Lực (F)","definition":"a push or pull on an object with a specific magnitude and direction; can be represented by vectors; can be expressed as a multiple of a standard force; the SI unit of force is the Newton (N)","definitionVi":"Sự đẩy hoặc kéo tác dụng lên vật làm thay đổi vận tốc hoặc làm biến dạng vật (đơn vị SI: Newton, N).","memoryTipVi":"1 N = 1 kg·m/s²."},{"term":"free-body diagram","termVi":"Sơ đồ lực (Biểu diễn các lực tác dụng lên vật)","definition":"a diagram showing all external forces acting on a body","definitionVi":"Hình vẽ tách riêng một vật và vẽ tất cả các vectơ ngoại lực tác dụng lên nó.","memoryTipVi":"Bước số 1 bắt buộc trước khi viết phương trình Định luật II Newton!"},{"term":"net external force","termVi":"Hợp ngoại lực (F_net)","definition":"the sum of all external forces acting on an object or system","definitionVi":"Tổng vectơ của tất cả các ngoại lực tác dụng lên một hệ.","memoryTipVi":"F_net = ΣF."},{"term":"net force","termVi":"Hợp lực","definition":"the sum of all forces acting on an object or system","definitionVi":"Tổng vectơ tất cả các lực tác dụng lên một vật.","memoryTipVi":"Khi F_net = 0, vật đứng yên hoặc chuyển động thẳng đều."}],"assessments":[{"uid":"hsphys.ch04.sec01.q002","sourceId":"fs-idp86096448","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Do two bodies have to be in physical contact to exert a force upon one another?","images":[],"choices":[{"label":"a","text":"No, the gravitational force is a field force and does not require physical contact to exert a force."},{"label":"b","text":"No, the gravitational force is a contact force and does not require physical contact to exert a force."},{"label":"c","text":"Yes, the gravitational force is a field force and requires physical contact to exert a force."},{"label":"d","text":"Yes, the gravitational force is a contact force and requires physical contact to exert a force."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec01.q004","sourceId":"fs-idp41989680","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Which forces can be represented in a free-body diagram?","images":[],"choices":[{"label":"a","text":"Internal forces"},{"label":"b","text":"External forces"},{"label":"c","text":"Both internal and external forces"},{"label":"d","text":"A body that is not influenced by any force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec01.q005","sourceId":"fs-idp98963232","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"What is dynamics?","images":[],"choices":[{"label":"a","text":"Dynamics is the study of internal forces."},{"label":"b","text":"Dynamics is the study of forces and their effect on motion."},{"label":"c","text":"Dynamics describes the motion of points, bodies, and systems without consideration of the cause of motion."},{"label":"d","text":"Dynamics describes the effect of forces on each other."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec01.q006","sourceId":"fs-idm5179520","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Two forces acting on an object are perpendicular to one another. How would you draw these in a free-body diagram?","images":[],"choices":[{"label":"a","text":"The two force arrows will be drawn at a right angle to one another."},{"label":"b","text":"The two force arrows will be pointing in opposite directions."},{"label":"c","text":"The two force arrows will be at a 45° angle to one another."},{"label":"d","text":"The two force arrows will be at a 180° angle to one another."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec01.q007","sourceId":"eip-id1166851246933","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"A free-body diagram shows the forces acting on an object. How is that object represented in the diagram?","images":[],"choices":[{"label":"a","text":"A single point"},{"label":"b","text":"A square box"},{"label":"c","text":"A unit circle"},{"label":"d","text":"The object as it is"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec01.q008","sourceId":"fs-idp41742048","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Only two forces are acting on an object: force A to the left and force B to the right. If force B is greater than force A, in which direction will the object move, given that the object starts from rest?","images":[],"choices":[{"label":"a","text":"To the right"},{"label":"b","text":"To the left"},{"label":"c","text":"Upward"},{"label":"d","text":"The object does not move"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec01.q009","sourceId":"fs-idp36032720","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"In a free-body diagram, the arrows representing tension and weight have the same length but point away from one another. What does this indicate?","images":[],"choices":[{"label":"a","text":"They are equal in magnitude and act in the same direction."},{"label":"b","text":"They are equal in magnitude and act in opposite directions."},{"label":"c","text":"They are unequal in magnitude and act in the same direction."},{"label":"d","text":"They are unequal in magnitude and act in opposite directions."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec01.q010","sourceId":"eip-id1166850222565","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"An object is at rest. Two forces, X and Y, are acting on it. Force X has a magnitude of x and acts in the downward direction. What is the magnitude and direction of Y, given that the object remains at rest?","images":[],"choices":[{"label":"a","text":"The magnitude is x and points in the upward direction."},{"label":"b","text":"The magnitude is 2 x and points in the upward direction."},{"label":"c","text":"The magnitude is x and points in the downward direction."},{"label":"d","text":"The magnitude is 2 x and points in the downward direction."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec01.q011","sourceId":"eip-id1166849933507","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Three forces, A, B, and C, are acting on the same object with magnitudes a, b , and c , respectively. Force A acts to the right, force B acts to the left, and force C acts downward. What is a necessary condition for the object to move straight down?","images":[],"choices":[{"label":"a","text":"The magnitude of force A must be greater than the magnitude of force B, so a > b."},{"label":"b","text":"The magnitude of force A must be equal to the magnitude of force B, so a = b."},{"label":"c","text":"The magnitude of force A must be greater than the magnitude of force C, so A > C."},{"label":"d","text":"The magnitude of force C must be greater than the magnitude of forces A or B, so A < C > B."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec01.q012","sourceId":"fs-idp7481504","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which of the following is a physical quantity that can be described by dynamics but not by kinematics?","images":[],"choices":[{"label":"a","text":"Velocity"},{"label":"b","text":"Acceleration"},{"label":"c","text":"Force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec01.q013","sourceId":"fs-idp54387872","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which of the following is used to represent an object in a free-body diagram?","images":[],"choices":[{"label":"a","text":"A point"},{"label":"b","text":"A line"},{"label":"c","text":"A vector"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec01.q014","sourceId":"fs-idp54306832","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"True or FalseAn external force is defined as a force generated outside the system of interest that acts on an object inside the system.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec01.q016","sourceId":"fs-idp5719552","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A body is pushed downward by a force of 5 units and upward by a force of 2 units. How would you draw a free-body diagram to represent this?","images":[],"choices":[{"label":"a","text":"Two force vectors acting at a point, both pointing up with lengths of 5 units and 2 units"},{"label":"b","text":"Two force vectors acting at a point, both pointing down with lengths of 5 units and 2 units"},{"label":"c","text":"Two force vectors acting at a point, one pointing up with a length of 5 units and the other pointing down with a length of 2 units"},{"label":"d","text":"Two force vectors acting at a point, one pointing down with a length of 5 units and the other pointing up with a length of 2 units"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec01.q017","sourceId":"fs-idp19848160","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A body is pushed eastward by a force of four units and southward by a force of three units. How would you draw a free-body diagram to represent this?","images":[],"choices":[{"label":"a","text":"Two force vectors acting at a point, one pointing left with a length of 4 units and the other pointing down with a length of 3 units"},{"label":"b","text":"Two force vectors acting at a point, one pointing left with a length of 4 units and the other pointing up with a length of 3 units"},{"label":"c","text":"Two force vectors acting at a point, one pointing right with a length of 4 units and the other pointing down with a length of 3 units"},{"label":"d","text":"Two force vectors acting at a point, one pointing right with a length of 4 units and the other pointing up with a length of 3 units"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec01.q018","sourceId":"fs-idp19716928","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"True or FalseWhen two unequal forces act on a body, the body will not move in the direction of the weaker force.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec01.q019","sourceId":"fs-idm10865536","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"In the figure given, what is F restore ? What is its magnitude?","images":[{"sourceId":"fs-id1164566008214","filename":"CNX_HSPhysics_04_01_spring_img.jpg","relativePath":"media/CNX_HSPhysics_04_01_spring_img.jpg","alt":"Image a shows a spring with a handle connected to a weight. The length of the spring is x. Image b shows a hand pulling on the spring. The length that the spring extends after being pulled is labeled Triangle x. An arrow pointing from the hand to the weight is labeled F subscript restore. Image c shows a scale with a measurement of 6. The length from 0 to 6 is labeled triangle x. An arrow pointing from the tip of the scale to 6 is labeled F subscript restore."}],"choices":[{"label":"a","text":"F restore is the force exerted by the hand on the spring, and it pulls to the right."},{"label":"b","text":"F restore is the force exerted by the spring on the hand, and it pulls to the left."},{"label":"c","text":"F restore is the force exerted by the hand on the spring, and it pulls to the left."},{"label":"d","text":"F restore is the force exerted by the spring on the hand, and it pulls to the right."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":0,"subsectionCount":2,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":6,"assessmentCount":16}},{"uid":"hsphys.ch04.sec02","moduleId":"m54138","number":"4.2","slug":"newton-s-first-law-of-motion-inertia","title":"Newton's First Law of Motion: Inertia","isIntroduction":false,"learningObjectives":["Describe Newton’s first law and friction, and","Discuss the relationship between mass and inertia."],"bilingualGuide":{"notebookSummaryVi":"Định luật I Newton (Quán tính — Inertia), phân biệt Khối lượng (Mass) và vai trò của Lực ma sát (Friction).","wordProblemCues":[{"phraseEn":"constant velocity / equilibrium","meaningVi":"Chuyển động thẳng đều / Cân bằng → Hợp lực = 0","mathNotation":"F_net = 0"}],"commonTrapsVi":["Vật đang chuyển động thẳng đều KHÔNG cần hợp lực duy trì — lực chỉ cần để THAY ĐỔI vận tốc!"]},"keyEquations":[{"name":"Newton's first law of motion","formula":"\\({\\mathbf{F}}_{\\text{net}} = 0\\) or \\(\\Sigma \\mathbf{F} = 0\\)"}],"subsections":[{"uid":"hsphys.ch04.sec02.sub01","title":"Newton’s First Law and Friction","summaryVi":null,"paragraphs":["Newton’s first law of motion states the following:","At first glance, this law may seem to contradict your everyday experience. You have probably noticed that a moving object will usually slow down and stop unless some effort is made to keep it moving. The key to understanding why, for example, a sliding box slows down (seemingly on its own) is to first understand that a net external force acts on the box to make the box slow down. Without this net external force, the box would continue to slide at a constant velocity (as stated in Newton’s first law of motion). What force acts on the box to slow it down? This force is called friction . Generally, friction is an external force that acts opposite to the direction of relative motion or to prevent slipping. We further identify different types of friction. Kinetic friction is a force by a surface parallel to the surface that opposes the motion of a sliding object and causes it to slow down. When the friction prevents the object from sliding, it is called static friction. Rolling resistance impedes the rolling of a wheel. Drag opposes and slows the motion of an object through a fluid (see [Figure 4.2]). Think of friction as a resistance to motion that slows things down.","Consider an air hockey table. When the air is turned off, the puck slides only a short distance before friction slows it to a stop. However, when the air is turned on, it lifts the puck slightly, so the puck experiences very little friction as it moves over the surface. With friction almost eliminated, the puck glides along with very little change in speed. On a frictionless surface, the puck would experience no net external force (ignoring air resistance, which is also a form of friction). Additionally, if we know enough about friction, we can accurately predict how quickly objects will slow down.","Now let’s think about another example. A man pushes a box across a floor at constant velocity by applying a force of\n+50 N. (The positive sign indicates that, by convention, the direction of motion is to the right.) What is the force of friction that opposes the motion? The force of friction must be -50 N. Why? According to Newton’s first law of motion, any object moving at constant velocity has no net external force acting upon it, which means that the sum of the forces acting on the object must be zero. The mathematical way to say that no net external force acts on an object is \\({\\mathbf{F}}_{\\text{net}} = 0\\) or \\(\\Sigma \\mathbf{F} = 0.\\) So if the man applies +50 N of force, then the force of friction must be -50 N for the two forces to add up to zero (that is, for the two forces to cancel each other). Whenever you encounter the phrase at constant velocity , Newton’s first law tells you that the net external force is zero.","The force of friction depends on two factors: the coefficient of friction and the normal force . For any two surfaces that are in contact with one another, the coefficient of friction is a constant that depends on the nature of the surfaces. The normal force is the force exerted by a surface that pushes on an object out, perpendicular to the surface in response to the object’s pushing into the surface. The normal force prevents the object from penetrating the surface. In equation form, the force of friction is","where μ is the coefficient of friction and N is the normal force. (The coefficient of friction is discussed in more detail in another chapter, and the normal force is discussed in more detail in the section Newton's Third Law of Motion .)","Recall from the section on Force that a net external force acts from outside on the object of interest. A more precise definition is that it acts on the system of interest. A system is one or more objects that you choose to study. It is important to define the system at the beginning of a problem to figure out which forces are external and need to be considered, and which are internal and can be ignored.","For example, in [Figure 4.2] (a), two children push a third child in a wagon at a constant velocity. The system of interest is the wagon plus the small child, as shown in part (b) of the figure. The two children behind the wagon exert external forces on this system ( F 1, F 2). Friction f acting on the wheels is another external force acting on the system. Two more external forces act on the system: the weight W of the system pulling down and the normal force N of the ground pushing up. Notice that the wagon is not accelerating vertically, so Newton’s first law tells us that the normal force balances the weight. Because the wagon is moving forward at a constant velocity, the force of friction must have the same strength as the sum of the forces applied by the two children."],"figures":[{"sourceId":"fs-idp77919456","filename":"CNX_HSPhysics_04_02_friction.jpg","relativePath":"media/CNX_HSPhysics_04_02_friction.jpg","alt":"A rectangular box is on a flat surface. A velocity vector indicates that the box is moving to the right. A friction force vector at the center of the box points to the left. A Newton force vector at the center of the box points upward. A weight force vector at the center of the box is labeled in milligrams and points downward. A free body diagram illustrates the three vectors, and x and y-axes are shown for reference."},{"sourceId":"fs-idp78281072","filename":"CNX_HSPhysics_04_02_wagon.jpg","relativePath":"media/CNX_HSPhysics_04_02_wagon.jpg","alt":"Two diagrams are shown. In the top diagram, two children are pushing a third child who is sitting in a wagon. The forces exerted by the children pushing the wagon are labeled F1 and F2 and point to the right in the direction that the wagon is facing. A friction force vector below the wagon points to the left. A Newton force vector below the wagon points upward. A weight force vector below the wagon points downward. In the bottom diagram, only the child in the wagon is shown. The F1 and F2 vectors are shown ahead of the wagon pointing to the right. The Newton force vector is above the wagon and is pointing upward. The weight force vector is below the wagon and points downward."}],"tables":[]},{"uid":"hsphys.ch04.sec02.sub02","title":"Mass and Inertia","summaryVi":null,"paragraphs":["Inertia is the tendency for an object at rest to remain at rest, or for a moving object to remain in motion in a straight line with constant speed. This key property of objects was first described by Galileo. Later, Newton incorporated the concept of inertia into his first law, which is often referred to as the law of inertia .","As we know from experience, some objects have more inertia than others. For example, changing the motion of a large truck is more difficult than changing the motion of a toy truck. In fact, the inertia of an object is proportional to the mass of the object. Mass is a measure of the amount of matter (or stuff ) in an object. The quantity or amount of matter in an object is determined by the number and types of atoms the object contains. Unlike weight (which changes if the gravitational force changes), mass does not depend on gravity. The mass of an object is the same on Earth, in orbit, or on the surface of the moon. In practice, it is very difficult to count and identify all of the atoms and molecules in an object, so mass is usually not determined this way. Instead, the mass of an object is determined by comparing it with the standard kilogram. Mass is therefore expressed in kilograms.","In this simulation, you will first explore net force by placing blue people on the left side of a tug-of-war rope and red people on the right side of the rope (by clicking people and dragging them with your mouse). Experiment with changing the number and size of people on each side to see how it affects the outcome of the match and the net force. Hit the \"Go!\" button to start the match, and the “reset all” button to start over.","Next, click on the Friction tab. Try selecting different objects for the person to push. Slide the applied force button to the right to apply force to the right, and to the left to apply force to the left. The force will continue to be applied as long as you hold down the button. See the arrow representing friction change in magnitude and direction, depending on how much force you apply. Try increasing or decreasing the friction force to see how this change affects the motion.","Click on the tab for the Acceleration Lab and check the Sum of Forces option. Push the box to the right and then release. Notice which direction the sum of forces arrow points after the person stops pushing the box and lets it continue moving to the right on its own. At this point, in which direction is the net force, the sum of forces, pointing? Why?"],"figures":[],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch04.sec02.feat01","type":"tip","title":"Tips for Success","text":"In everyday language, people often use the terms weight and mass interchangeably—but this is not correct. Weight is actually a force. (We cover this topic in more detail in the section Newton's Second Law of Motion .)","images":[]}],"summaryPoints":["Newton’s first law states that a body at rest remains at rest or, if moving, remains in motion in a straight line at a constant speed, unless acted on by a net external force. This law is also known as the law of inertia.","Inertia is the tendency of an object at rest to remain at rest or, if moving, to remain in motion at constant velocity. Inertia is related to an object’s mass.","Friction is a force that opposes motion and causes an object or system to slow down.","Mass is the quantity of matter in a substance."],"glossary":[{"term":"friction","termVi":"Lực ma sát (f)","definition":"an external force that acts opposite to the direction of motion or, for when there is no relative motion, in the direction needed to prevent slipping","definitionVi":"Lực cản trở sự trượt (hoặc xu hướng trượt) giữa hai bề mặt tiếp xúc.","memoryTipVi":"Luôn ngược chiều chuyển động trượt tương đối."},{"term":"inertia","termVi":"Quán tính","definition":"the tendency of an object at rest to remain at rest, or for a moving object to remain in motion in a straight line and at a constant speed","definitionVi":"Xu hướng bảo toàn trạng thái đứng yên hoặc chuyển động thẳng đều của vật.","memoryTipVi":"Khối lượng (Mass) là thước đo mức quán tính!"},{"term":"law of inertia","termVi":"Định luật quán tính (Định luật I Newton)","definition":"Newton’s first law of motion: a body at rest remains at rest or, if in motion, remains in motion at a constant speed in a straight line, unless acted on by a net external force; also known as the law of inertia","definitionVi":"Tên gọi khác của Định luật I Newton.","memoryTipVi":"Không có hợp lực → không có gia tốc (a = 0)."},{"term":"mass","termVi":"Khối lượng (m)","definition":"the quantity of matter in a substance; the SI unit of mass is the kilogram","definitionVi":"Lượng vật chất trong vật và là thước đo quán tính (đơn vị SI: kg, vô hướng, không đổi dù ở Trái Đất hay Mặt Trăng).","memoryTipVi":"⚠️ False Friend: Mass (kg) ≠ Weight (Trọng lượng, N)!"},{"term":"Newton’s first law of motion","termVi":"Định luật I Newton","definition":"a body at rest remains at rest or, if in motion, remains in motion at a constant speed in a straight line, unless acted on by a net external force; also known as the law of inertia","definitionVi":"Một vật đứng yên sẽ tiếp tục đứng yên, vật đang chuyển động sẽ tiếp tục chuyển động thẳng đều nếu hợp lực bằng 0.","memoryTipVi":"F_net = 0 ⇔ v = const."},{"term":"system","termVi":"Hệ vật","definition":"one or more objects of interest for which only the forces acting on them from the outside are considered, but not the forces acting between them or inside them","definitionVi":"Một vật hoặc nhóm các vật được chọn để khảo sát.","memoryTipVi":"Cần xác định rõ biên giới của hệ trước khi vẽ Free-Body Diagram."},{"term":"rolling resistance","termVi":"Lực cản lăn (Ma sát lăn)","definition":"various forces that may impede a rolling wheel; these include axle friction, drag, and imperfectly elastic deformation of the wheel and/or surface","definitionVi":"Lực cản cản trở chuyển động lăn của bánh xe trên mặt đường.","memoryTipVi":"Nhỏ hơn nhiều so với ma sát trượt."}],"assessments":[{"uid":"hsphys.ch04.sec02.q001","sourceId":"fs-idp47938160","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What does Newtons first law state?","images":[],"choices":[{"label":"a","text":"A body at rest tends to remain at rest and a body in motion tends to remain in motion at a constant acceleration unless acted on by a net external force."},{"label":"b","text":"A body at rest tends to remain at rest and a body in motion tends to remain in motion at a constant velocity unless acted on by a net external force."},{"label":"c","text":"The rate of change of momentum of a body is directly proportional to the external force applied to the body."},{"label":"d","text":"The rate of change of momentum of a body is inversely proportional to the external force applied to the body."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec02.q002","sourceId":"fs-idp97846624","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"According to Newtons first law, a body in motion tends to remain in motion at a constant velocity. However, when you slide an object across a surface, the object eventually slows down and stops. Why?","images":[],"choices":[{"label":"a","text":"The object experiences a frictional force exerted by the surface, which opposes its motion."},{"label":"b","text":"The object experiences the gravitational force exerted by Earth, which opposes its motion"},{"label":"c","text":"The object experiences an internal force exerted by the body itself, which opposes its motion."},{"label":"d","text":"The object experiences a pseudo-force from the body in motion, which opposes its motion."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec02.q004","sourceId":"fs-idp86925600","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What is mass? What does it depend on?","images":[],"choices":[{"label":"a","text":"Mass is the weight of an object, and it depends on the gravitational force acting on the object."},{"label":"b","text":"Mass is the weight of an object, and it depends on the number and types of atoms in the object."},{"label":"c","text":"Mass is the quantity of matter contained in an object, and it depends on the gravitational force acting on the object."},{"label":"d","text":"Mass is the quantity of matter contained in an object, and it depends on the number and types of atoms in the object."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec02.q005","sourceId":"fs-idm7722272","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"A ball rolls along the ground, moving from north to south. What direction is the frictional force that acts on the ball?","images":[],"choices":[{"label":"a","text":"North to south"},{"label":"b","text":"South to north"},{"label":"c","text":"West to east"},{"label":"d","text":"East to west"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec02.q006","sourceId":"fs-idp3665856","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"The tires you choose to drive over icy roads will create more friction with the road than your summer tires. Give another example where more friction is desirable.","images":[],"choices":[{"label":"a","text":"Childrens slide"},{"label":"b","text":"Air hockey table"},{"label":"c","text":"Ice-skating rink"},{"label":"d","text":"Jogging track"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec02.q007","sourceId":"eip-id1166849691780","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"How do you express, mathematically, that no external force is acting on a body?","images":[],"choices":[{"label":"a","text":"F net = -1"},{"label":"b","text":"F net = 0"},{"label":"c","text":"F net = 1"},{"label":"d","text":"F net = ∞"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec02.q008","sourceId":"fs-idp5127360","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Two people push a cart on a horizontal surface by applying forces F 1 and F 2 in the same direction. Is the magnitude of the net force acting on the cart, F net , equal to, greater than, or less than F 1 + F 2 ? Why?","images":[],"choices":[{"label":"a","text":"F net < F 1 + F 2 because the net force will not include the frictional force."},{"label":"b","text":"F net = F 1 + F 2 because the net force will not include the frictional force"},{"label":"c","text":"F net < F 1 + F 2 because the net force will include the component of frictional force"},{"label":"d","text":"F net = F 1 + F 2 because the net force will include the frictional force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec02.q009","sourceId":"fs-idp44522016","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"True or False: A book placed on a balance scale is balanced by a standard 1-kg iron weight placed on the opposite side of the balance. If these objects are taken to the moon and a similar exercise is performed, the balance is still level because gravity is uniform on the moons surface as it is on Earths surface.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec02.q010","sourceId":"fs-idp21966320","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which of the following does the friction force NOT depend on?","images":[],"choices":[{"label":"a","text":"The normal force on the object"},{"label":"b","text":"The nature of the contact surface"},{"label":"c","text":"The speed of the object"},{"label":"d","text":"The direction of the object's motion"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec02.q011","sourceId":"fs-idp6477280","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is another name for Newtons first law?","images":[],"choices":[{"label":"a","text":"Law of infinite motion"},{"label":"b","text":"Law of inertia"},{"label":"c","text":"Law of friction"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec02.q012","sourceId":"eip-id1166850087984","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"True or FalseA rocket is launched into space and escapes Earths gravitational pull. It will continue to travel in a straight line until it is acted on by another force.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec02.q013","sourceId":"eip-id1166849285606","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A 2,000-kg car is sitting at rest in a parking lot. A bike and rider with a total mass of 60 kg are traveling along a road at 10 km/h. Which system has more inertia? Why?","images":[],"choices":[{"label":"a","text":"The car has more inertia, as its mass is greater than the mass of the bike."},{"label":"b","text":"The bike has more inertia, as its mass is greater than the mass of the car."},{"label":"c","text":"The car has more inertia, as its mass is less than the mass of the bike."},{"label":"d","text":"The bike has more inertia, as its mass is less than the mass of the car."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec02.q014","sourceId":"fs-idp11451872","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A body with mass m is pushed along a horizontal surface by a force F and is opposed by a frictional force f . How would you draw a free-body diagram to represent this situation?","images":[],"choices":[{"label":"a","text":"A dot with an arrow pointing right, labeled F, and an arrow pointing left, labeled f , that is of equal length or shorter than F"},{"label":"b","text":"A dot with an arrow pointing right, labeled F, and an arrow pointing right, labeled f , that is of equal length or shorter than F"},{"label":"c","text":"A dot with an arrow pointing right, labeled F, and a smaller arrow pointing up, labeled f , that is of equal length or longer than F"},{"label":"d","text":"A dot with an arrow pointing right, labeled F, and a smaller arrow pointing down, labeled f , that is of equal length or longer than F"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec02.q016","sourceId":"fs-idp6160304","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Two similar boxes rest on a table. One is empty and the other is filled with pebbles. Without opening or lifting either, how can you tell which box is full? Why?","images":[],"choices":[{"label":"a","text":"By applying an internal force; whichever box accelerates faster is lighter and so must be empty"},{"label":"b","text":"By applying an internal force; whichever box accelerates faster is heavier and so the other box must be empty"},{"label":"c","text":"By applying an external force; whichever box accelerates faster is lighter and so must be empty"},{"label":"d","text":"By applying an external force; whichever box accelerates faster is heavier and so the other box must be empty"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec02.q017","sourceId":"fs-idp37976512","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"True or FalseAn external force is required to set a stationary object in motion in outer space away from all gravitational influences and atmospheric friction.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec02.q019","sourceId":"fs-idp77332816","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"A person pushes a box from left to right and then lets the box slide freely across the floor. The box slows down as it slides across the floor. When the box is sliding freely, what is the direction of the net external force?","images":[],"choices":[{"label":"a","text":"The net external force acts from left to right."},{"label":"b","text":"The net external force acts from right to left."},{"label":"c","text":"The net external force acts upward."},{"label":"d","text":"The net external force acts downward."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":1,"subsectionCount":2,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":7,"assessmentCount":16}},{"uid":"hsphys.ch04.sec03","moduleId":"m54142","number":"4.3","slug":"newton-s-second-law-of-motion","title":"Newton's Second Law of Motion","isIntroduction":false,"learningObjectives":["Describe Newton’s second law, both verbally and mathematically","Use Newton’s second law to solve problems"],"bilingualGuide":{"notebookSummaryVi":"Định luật II Newton (F_net = ma) và phân biệt dứt khoát Khối lượng (Mass, kg) với Trọng lượng (Weight, W = mg, N).","wordProblemCues":[{"phraseEn":"weight W = mg","meaningVi":"Trọng lượng (lực hút Trái Đất)","mathNotation":"W = m·g"}],"commonTrapsVi":["⚠️ False Friend: Mass (khối lượng, kg) là bất biến; Weight (trọng lượng, N) thay đổi theo hành tinh!"]},"keyEquations":[{"name":"Newton’s second law of motion","formula":"\\({\\mathbf{F}}_{\\text{net}} = m\\mathbf{a}\\) or \\(\\Sigma \\text{F} = m\\text{a}\\)"},{"name":"Newton’s second law of motion to solve acceleration","formula":"\\(\\mathbf{a} = \\frac{{\\mathbf{F}}_{\\text{net}}}{m}\\text{or}\\mathbf{a} = \\frac{\\Sigma \\mathbf{F}}{m}\\)"},{"name":"Newton’s second law of motion to solve weight","formula":"\\(\\mathbf{W} = m\\mathbf{g}\\)"}],"subsections":[{"uid":"hsphys.ch04.sec03.sub01","title":"Describing Newton’s Second Law of Motion","summaryVi":null,"paragraphs":["Newton’s first law considered bodies at rest or bodies in motion at a constant velocity . The other state of motion to consider is when an object is moving with a changing velocity, which means a change in the speed and/or the direction of motion. This type of motion is addressed by Newton’s second law of motion , which states how force causes changes in motion. Newton’s second law of motion is used to calculate what happens in situations involving forces and motion, and it shows the mathematical relationship between force, mass , and acceleration . Mathematically, the second law is most often written as","where F net (or ∑ F ) is the net external force , m is the mass of the system, and a is the acceleration. Note that F net and ∑ F are the same because the net external force is the sum of all the external forces acting on the system.","First, what do we mean by a change in motion ? A change in motion is simply a change in velocity: the speed of an object can become slower or faster, the direction in which the object is moving can change, or both of these variables may change. A change in velocity means, by definition, that an acceleration has occurred. Newton’s first law says that only a nonzero net external force can cause a change in motion, so a net external force must cause an acceleration. Note that acceleration can refer to slowing down or to speeding up. Acceleration can also refer to a change in the direction of motion with no change in speed, because acceleration is the change in velocity divided by the time it takes for that change to occur, and velocity is defined by speed and direction.","From the equation \\({\\text{F}}_{\\text{net}} = m\\text{a},\\) we see that force is directly proportional to both mass and acceleration, which makes sense. To accelerate two objects from rest to the same velocity, you would expect more force to be required to accelerate the more massive object. Likewise, for two objects of the same mass, applying a greater force to one would accelerate it to a greater velocity.","Now, let’s rearrange Newton’s second law to solve for acceleration. We get","In this form, we can see that acceleration is directly proportional to force, which we write as","where the symbol \\(∝\\) means proportional to .","This proportionality mathematically states what we just said in words: acceleration is directly proportional to the net external force. When two variables are directly proportional to each other, then if one variable doubles, the other variable must double. Likewise, if one variable is reduced by half, the other variable must also be reduced by half. In general, when one variable is multiplied by a number, the other variable is also multiplied by the same number. It seems reasonable that the acceleration of a system should be directly proportional to and in the same direction as the net external force acting on the system. An object experiences greater acceleration when acted on by a greater force.","It is also clear from the equation \\(\\mathbf{a} = {\\mathbf{F}}_{\\text{net}}\\text{/}m\\) that acceleration is inversely proportional to mass, which we write as","Inversely proportional means that if one variable is multiplied by a number, the other variable must be divided by the same number. Now, it also seems reasonable that acceleration should be inversely proportional to the mass of the system. In other words, the larger the mass (the inertia), the smaller the acceleration produced by a given force. This relationship is illustrated in [Figure 4.3], which shows that a given net external force applied to a basketball produces a much greater acceleration than when applied to a car."],"figures":[{"sourceId":"fs-idm22396928","filename":"CNX_HSPhysics_04_03_basketball.jpg","relativePath":"media/CNX_HSPhysics_04_03_basketball.jpg","alt":"Three diagrams are shown: a, b, and c. Diagram a shows standing person facing to the right, pushing forward on a basketball. The basketball is labeled m one for mass one. A force vector is labeled F and is pointing to the right. An acceleration vector is labeled a one and is also pointing to the right. Diagram b shows the same person in the same standing position, pushing forward with the same force, but on a car. The car is labeled m two for mass two. A force vector is labeled F and is pointing to the right. An acceleration vector is labeled a two and is also pointing to the right. Diagram c shows free body diagrams for diagrams a and b, illustrating that the free body diagrams are identical because the forces acting on both masses were the same."}],"tables":[]},{"uid":"hsphys.ch04.sec03.sub02","title":"Applying Newton’s Second Law","summaryVi":null,"paragraphs":["Before putting Newton’s second law into action, it is important to consider units.\nThe equation \\({\\mathbf{F}}_{\\text{net}} = m\\mathbf{a}\\) is used to define the units of force in terms of the three basic units of mass, length, and time (recall that acceleration has units of length divided by time squared). The SI unit of force is called the newton (abbreviated N) and is the force needed to accelerate a 1-kg system at the rate of 1 m/s 2 . That is, because \\({\\mathbf{F}}_{\\text{net}} = m\\mathbf{a},\\) we have","One of the most important applications of Newton’s second law is to calculate weight (also known as the gravitational force ), which is usually represented mathematically as W . When people talk about gravity , they don’t always realize that it is an acceleration. When an object is dropped, it accelerates toward the center of Earth. Newton’s second law states that the net external force acting on an object is responsible for the acceleration of the object. If air resistance is negligible, the net external force on a falling object is only the gravitational force (i.e., the weight of the object).","Weight can be represented by a vector because it has a direction. Down is defined as the direction in which gravity pulls, so weight is normally considered a downward force. By using Newton’s second law, we can figure out the equation for weight.","Consider an object with mass m falling toward Earth. It experiences only the force of gravity (i.e., the gravitational force or weight), which is represented by W. Newton’s second law states that \\({\\mathbf{F}}_{\\text{net}} = m\\mathbf{a}.\\) Because the only force acting on the object is the gravitational force, we have \\({\\mathbf{F}}_{\\text{net}} = \\mathbf{W}.\\) We know that the acceleration of an object due to gravity is g , so we have \\(\\mathbf{a} = \\mathbf{g}.\\) Substituting these two expressions into Newton’s second law gives","This is the equation for weight—the gravitational force on a mass m . On Earth, \\(\\mathbf{g} = 9.80{\\text{m/s}}^{\\text{2}},\\) so the weight (disregarding for now the direction of the weight) of a 1.0-kg object on Earth is","Although most of the world uses newtons as the unit of force, in the United States the most familiar unit of force is the pound (lb), where 1 N = 0.225 lb.","Recall that although gravity acts downward, it can be assigned a positive or negative value, depending on what the positive direction is in your chosen coordinate system. Be sure to take this into consideration when solving problems with weight. When the downward direction is taken to be negative, as is often the case, acceleration due to gravity becomes –g = -9.8 m/s 2 and the weight force is –mg.","When the net external force on an object is its weight, we say that it is in freefall . In this case, the only force acting on the object is the force of gravity. On the surface of Earth, when objects fall downward toward Earth, they are never truly in freefall because there is always some upward force due to air resistance that acts on the object (and there is also the buoyancy force of air, which is similar to the buoyancy force in water that keeps boats afloat).","Gravity varies slightly over the surface of Earth, so the weight of an object depends very slightly on its location on Earth. Weight varies dramatically away from Earth’s surface. On the moon, for example, the acceleration due to gravity is only 1.67 m/s 2 . Because weight depends on the force of gravity, a 1.0-kg mass weighs 9.8 N on Earth and only about 1.7 N on the moon.","It is important to remember that weight and mass are very different, although they are closely related. Mass is the quantity of matter in an object (how much stuff there is, or how hard it is to accelerate it) and does not vary, but weight is the gravitational force on an object and is proportional to the force of gravity. It is easy to confuse the two, because our experience is confined to Earth, and the weight of an object is essentially the same no matter where you are on Earth. Adding to the confusion, the terms mass and weight are often used interchangeably in everyday language; for example, our medical records often show our weight in kilograms, but never in the correct unit of newtons."],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch04.sec03.ex01","number":"4.3.1","title":"What Acceleration Can a Person Produce when Pushing a Lawn Mower?","problem":"Suppose that the net external force (push minus friction) exerted on a lawn mower is 51 N parallel to the ground. The mass of the mower is 240 kg. What is its acceleration?","problemImages":[{"sourceId":"fs-idp1621360","filename":"CNX_HSPhysics_04_03_mower_img.jpg","relativePath":"media/CNX_HSPhysics_04_03_mower_img.jpg","alt":"A man is facing to the right and is pushing a lawn mover forward. The force exerted on the lawn mower is labeled with a right-facing vector, F net."}],"strategy":"Because F net and m are given, the acceleration can be calculated directly from Newton’s second law: F net = m a .","solution":"Solving Newton’s second law for the acceleration, we find that the magnitude of the acceleration, a , is \\(\\mathbf{a} = \\frac{{\\mathbf{F}}_{\\text{net}}}{m}.\\) Entering the given values for net external force and mass gives\n\\(\\mathbf{a} = \\frac{51\\,\\text{N}}{240\\,\\text{kg}}\\)\nInserting the units \\(\\text{kg} \\cdot {\\text{m/s}}^{\\text{2}}\\) for N yields\n\\(\\mathbf{a} = \\frac{51\\,\\text{kg} \\cdot {\\text{m/s}}^{\\text{2}}}{240\\,\\text{kg}} = 0.21{\\text{m/s}}^{\\text{2}}\\text{.}\\)","solutionImages":[],"solutionTables":[],"discussion":"The acceleration is in the same direction as the net external force, which is parallel to the ground and to the right. There is no information given in this example about the individual external forces acting on the system, but we can say something about their relative magnitudes. For example, the force exerted by the person pushing the mower must be greater than the friction opposing the motion, because we are given that the net external force is in the direction in which the person pushes. Also, the vertical forces must cancel if there is no acceleration in the vertical direction (the mower is moving only horizontally). The acceleration found is reasonable for a person pushing a mower; the mower’s speed must increase by 0.21 m/s every second, which is possible. The time during which the mower accelerates would not be very long because the person’s top speed would soon be reached. At this point, the person could push a little less hard, because he only has to overcome friction."},{"uid":"hsphys.ch04.sec03.ex02","number":"4.3.2","title":"What Rocket Thrust Accelerates This Sled?","problem":"Prior to manned space flights, rocket sleds were used to test aircraft, missile equipment, and physiological effects on humans at high accelerations. Rocket sleds consisted of a platform mounted on one or two rails and propelled by several rockets. Calculate the magnitude of force exerted by each rocket, called its thrust, T , for the four-rocket propulsion system shown below. The sled’s initial acceleration is \\(49{\\text{m/s}}^{\\text{2}},\\) the mass of the system is 2,100 kg, and the force of friction opposing the motion is 650 N.","problemImages":[{"sourceId":"fs-idm28637824","filename":"CNX_HSPhysics_04_03_rocket_img.jpg","relativePath":"media/CNX_HSPhysics_04_03_rocket_img.jpg","alt":"An accelerating right-facing rocket sled is shown on tracks. Four thrust force vectors are behind the sled and are pointing to the right. An acceleration vector is above the sled and is pointing to the right. A friction force vector is in front of the sled and is pointing to the left. A Newton vector is below the sled and is pointing upward. A weight vector is also below the sled and is pointing downward. A free body diagram illustrates the force vectors."}],"strategy":"The system of interest is the rocket sled. Although forces act vertically on the system, they must cancel because the system does not accelerate vertically. This leaves us with only horizontal forces to consider. We’ll assign the direction to the right as the positive direction. See the free-body diagram in Figure 4.8.","solution":"We start with Newton’s second law and look for ways to find the thrust T of the engines. Because all forces and acceleration are along a line, we need only consider the magnitudes of these quantities in the calculations. We begin with\n\\({\\mathbf{F}}_{\\text{net}} = m\\mathbf{a},\\)\nwhere \\({\\mathbf{F}}_{\\text{net}}\\) is the net external force in the horizontal direction. We can see from Figure 4.8 that the engine thrusts are in the same direction (which we call the positive direction), whereas friction opposes the thrust. In equation form, the net external force is\n\\({\\mathbf{F}}_{\\text{net}} = 4\\mathbf{T} - \\mathbf{f}.\\)\nNewton’s second law tells us that F net = m a , so we get\n\\(m\\mathbf{a} = 4\\mathbf{T} - \\mathbf{f}.\\)\nAfter a little algebra, we solve for the total thrust 4 T :\n\\(4\\mathbf{T} = m\\mathbf{a} + \\mathbf{f},\\) which means that the individual thrust is\n\\(\\mathbf{T} = \\frac{m\\mathbf{a} + \\mathbf{f}}{4}.\\) Inserting the known values yields\n\\(\\mathbf{T} = \\frac{(2100{\\text{kg)(49 m/s}}^{2}) + 650\\,\\text{N}}{4} = 2.6 \\times {10}^{4}\\text{N}\\text{.}\\)","solutionImages":[],"solutionTables":[],"discussion":"The numbers are quite large, so the result might surprise you. Experiments such as this were performed in the early 1960s to test the limits of human endurance and to test the apparatus designed to protect fighter pilots in emergency ejections. Speeds of 1000 km/h were obtained, with accelerations of 45 g . (Recall that g, the acceleration due to gravity, is \\(\\text{9}{\\text{.80 m/s}}^{2}.\\) An acceleration of 45 g is 45 × 9\n.80 m/s\n2\n, which is approximately \\({\\text{440 m/s}}^{2}.\\) ) Living subjects are no longer used, and land speeds of 10,000 km/h have now been obtained with rocket sleds. In this example, as in the preceding example, the system of interest is clear. We will see in later examples that choosing the system of interest is crucial—and that the choice is not always obvious."}],"snapLabs":[{"uid":"hsphys.ch04.sec03.lab01","title":"Mass and Weight","text":"In this activity, you will use a scale to investigate mass and weight.\n1 bathroom scale\n1 table\nWhat do bathroom scales measure?\nWhen you stand on a bathroom scale, what happens to the scale? It depresses slightly. The scale contains springs that compress in proportion to your weight—similar to rubber bands expanding when pulled.\nThe springs provide a measure of your weight (provided you are not accelerating). This is a force in newtons (or pounds). In most countries, the measurement is now divided by 9.80 to give a reading in kilograms, which is a of mass. The scale detects weight but is calibrated to display mass.\nIf you went to the moon and stood on your scale, would it detect the same mass as it did on Earth?","images":[]}],"tipsAndFeatures":[{"uid":"hsphys.ch04.sec03.feat01","type":"tip","title":"Tips for Success","text":"Only net external force impacts the acceleration of an object. If more than one force acts on an object and you calculate the acceleration by using only one of these forces, you will not get the correct acceleration for that object.","images":[]}],"summaryPoints":["Acceleration is a change in velocity, meaning a change in speed, direction, or both.","An external force acts on a system from outside the system, as opposed to internal forces, which act between components within the system.","Newton’s second law of motion states that the acceleration of a system is directly proportional to and in the same direction as the net external force acting on the system, and inversely proportional to the system’s mass.","In equation form, Newton’s second law of motion is \\({\\mathbf{F}}_{\\text{net}} = m\\mathbf{a}\\) or Σ F = m a\n. This is sometimes written as \\(\\mathbf{a} = \\frac{{\\mathbf{F}}_{\\text{net}}}{m}\\) or \\(\\mathbf{a} = \\frac{\\Sigma \\mathbf{F}}{m}\\) .","The weight of an object of mass m is the force of gravity that acts on it. From Newton’s second law, weight is given by\n\\(\\text{W} = m\\text{g}\\text{.}\\)","If the only force acting on an object is its weight, then the object is in freefall."],"glossary":[{"term":"freefall","termVi":"Sự rơi tự do","definition":"a situation in which the only force acting on an object is the force of gravity","definitionVi":"Chuyển động của vật chỉ chịu tác dụng duy nhất của trọng lực.","memoryTipVi":"Trong rơi tự do, a = g = 9.8 m/s²."},{"term":"Newton’s second law of motion","termVi":"Định luật II Newton","definition":"the net external force, \\({\\mathbf{F}}_{\\text{net}}\\text{,}\\) on an object is proportional to and in the same direction as the acceleration of the object, a , and also proportional to the object’s mass, m ; defined mathematically as \\({\\mathbf{F}}_{\\text{net}} = m\\mathbf{a}\\) or Σ F = m a .","definitionVi":"Gia tốc của vật cùng hướng với hợp lực, tỉ lệ thuận với hợp lực và tỉ lệ nghịch với khối lượng: F_net = m·a.","memoryTipVi":"Phương trình quan trọng nhất của toàn bộ Cơ học cổ điển!"},{"term":"weight","termVi":"Trọng lượng (W = mg)","definition":"the force of gravity, W , acting on an object of mass m ; defined mathematically as W = m g , where g is the magnitude and direction of the acceleration due to gravity","definitionVi":"Lực hấp dẫn của Trái Đất (hoặc hành tinh) tác dụng lên vật (đại lượng vectơ, đơn vị Newton N).","memoryTipVi":"Lên Mặt Trăng: Mass (kg) giữ nguyên, nhưng Weight (N) giảm 6 lần!"}],"assessments":[{"uid":"hsphys.ch04.sec03.q001","sourceId":"fs-idm72827552","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What is the mathematical statement for Newtons second law of motion?","images":[],"choices":[{"label":"a","text":"F = m a"},{"label":"b","text":"F = 2 m a"},{"label":"c","text":"\\(\\text{F} = \\frac{m}{\\text{a}}\\)"},{"label":"d","text":"F = m a 2"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q002","sourceId":"fs-idm47302048","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Newtons second law describes the relationship between which quantities?","images":[],"choices":[{"label":"a","text":"Force, mass, and time"},{"label":"b","text":"Force, mass, and displacement"},{"label":"c","text":"Force, mass, and velocity"},{"label":"d","text":"Force, mass, and acceleration"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q004","sourceId":"fs-id1167066054738","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"If 1 N is equal to 0.225 lb, how many pounds is 5 N of force?","images":[],"choices":[{"label":"a","text":"0.045 lb"},{"label":"b","text":"1.125 lb"},{"label":"c","text":"2.025 lb"},{"label":"d","text":"5.000 lb"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q005","sourceId":"fs-id1167064774755","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"How much force needs to be applied to a 5-kg object for it to accelerate at 20 m/s 2 ?","images":[],"choices":[{"label":"a","text":"1 N"},{"label":"b","text":"10 N"},{"label":"c","text":"100 N"},{"label":"d","text":"1,000 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q006","sourceId":"fs-idm30049504","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"What does it mean for two quantities to be inversely proportional to each other?","images":[],"choices":[{"label":"a","text":"When one variable increases, the other variable decreases by a greater amount."},{"label":"b","text":"When one variable increases, the other variable also increases."},{"label":"c","text":"When one variable increases, the other variable decreases by the same factor."},{"label":"d","text":"When one variable increases, the other variable also increases by the same factor."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q007","sourceId":"eip-id1166851349087","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"True or False: Newton's second law can be interpreted based on Newton's first law.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q008","sourceId":"fs-idm73013152","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"From the equation for Newtons second law, we see that F net is directly proportional to a and that the constant of proportionality is m . What does this mean in a practical sense?","images":[],"choices":[{"label":"a","text":"An increase in applied force will cause an increase in acceleration if the mass is constant."},{"label":"b","text":"An increase in applied force will cause a decrease in acceleration if the mass is constant."},{"label":"c","text":"An increase in applied force will cause an increase in acceleration, even if the mass varies."},{"label":"d","text":"An increase in applied force will cause an increase in acceleration and mass."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q009","sourceId":"fs-id1167066054738","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"If 1 N is equal to 0.225 lb, how many pounds is 5 N of force?","images":[],"choices":[{"label":"a","text":"0.045 lb"},{"label":"b","text":"1.125 lb"},{"label":"c","text":"2.025 lb"},{"label":"d","text":"5.000 lb"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q010","sourceId":"fs-id1167064774755","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"How much force needs to be applied to a 5-kg object for it to accelerate at 20 m/s 2 ?","images":[],"choices":[{"label":"a","text":"1 N"},{"label":"b","text":"10 N"},{"label":"c","text":"100 N"},{"label":"d","text":"1,000 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q012","sourceId":"fs-idm87696080","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A bathroom scale shows your mass as 55 kg. What will it read on the moon?","images":[],"choices":[{"label":"a","text":"9.4 kg"},{"label":"b","text":"10.5 kg"},{"label":"c","text":"55.0 kg"},{"label":"d","text":"91.9 kg"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q013","sourceId":"fs-idm28211856","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"In the equation for Newtons second law, what does F net stand for?","images":[],"choices":[{"label":"a","text":"Internal force"},{"label":"b","text":"Net external force"},{"label":"c","text":"Frictional force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q014","sourceId":"fs-idm86357824","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is the SI unit of force?","images":[],"choices":[{"label":"a","text":"Kg"},{"label":"b","text":"dyn"},{"label":"c","text":"N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q015","sourceId":"eip-id1166851085385","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is the net external force on an object in freefall on Earth if you were to neglect the effect of air?","images":[],"choices":[{"label":"a","text":"The net force is zero."},{"label":"b","text":"The net force is upward with magnitude mg ."},{"label":"c","text":"The net force is downward with magnitude mg ."},{"label":"d","text":"The net force is downward with magnitude 9.8 N."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q016","sourceId":"eip-id1166851085657","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Two people push a 2,000-kg car to get it started. An acceleration of at least 5.0 m/s 2 is required to start the car. Assuming both people apply the same magnitude force, how much force will each need to apply if friction between the car and the road is 300 N?","images":[],"choices":[{"label":"a","text":"4850 N"},{"label":"b","text":"5150 N"},{"label":"c","text":"97000 N"},{"label":"d","text":"10300 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q017","sourceId":"fs-idm28687200","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A steadily rolling ball is pushed in the direction from east to west, which causes the ball to move faster in the same direction. What is the direction of the acceleration?","images":[],"choices":[{"label":"a","text":"North to south"},{"label":"b","text":"South to north"},{"label":"c","text":"East to west"},{"label":"d","text":"West to east"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q018","sourceId":"fs-idm12955920","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A ball travels from north to south at 60 km/h. After being hit by a bat, it travels from west to east at 60 km/h. Is there a change in velocity?","images":[],"choices":[{"label":"a","text":"Yes, because velocity is a scalar."},{"label":"b","text":"Yes, because velocity is a vector."},{"label":"c","text":"No, because velocity is a scalar."},{"label":"d","text":"No, because velocity is a vector"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q019","sourceId":"fs-idm43129888","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What is the weight of a 5-kg object on Earth and on the moon?","images":[],"choices":[{"label":"a","text":"On Earth the weight is 1.67 N, and on the moon the weight is 1.67 N."},{"label":"b","text":"On Earth the weight is 5 N, and on the moon the weight is 5 N."},{"label":"c","text":"On Earth the weight is 49 N, and on the moon the weight is 8.35 N."},{"label":"d","text":"On Earth the weight is 8.35 N, and on the moon the weight is 49 N."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q020","sourceId":"fs-idm101291824","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"An object weighs 294 N on Earth. What is its weight on the moon?","images":[],"choices":[{"label":"a","text":"50.1 N"},{"label":"b","text":"30.0 N"},{"label":"c","text":"249 N"},{"label":"d","text":"1461 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q021","sourceId":"fs-idm28221552","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"A 55-kg lady stands on a bathroom scale inside an elevator. The scale reads 70 kg. What do you know about the motion of the elevator?","images":[],"choices":[{"label":"a","text":"The elevator must be accelerating upward."},{"label":"b","text":"The elevator must be accelerating downward."},{"label":"c","text":"The elevator must be moving upward with a constant velocity."},{"label":"d","text":"The elevator must be moving downward with a constant velocity."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec03.q022","sourceId":"fs-idm68290608","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"True or FalseA skydiver initially accelerates in his jump. Later, he achieves a state of constant velocity called terminal velocity. Does this mean the skydiver becomes weightless?","images":[],"choices":[{"label":"a","text":"Yes"},{"label":"b","text":"No"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":3,"subsectionCount":2,"workedExampleCount":2,"snapLabCount":1,"glossaryCount":3,"assessmentCount":20}},{"uid":"hsphys.ch04.sec04","moduleId":"m54131","number":"4.4","slug":"newton-s-third-law-of-motion","title":"Newton's Third Law of Motion","isIntroduction":false,"learningObjectives":["Describe Newton’s third law, both verbally and mathematically","Use Newton’s third law to solve problems"],"bilingualGuide":{"notebookSummaryVi":"Định luật III Newton (Lực – Phản lực), Phản lực pháp tuyến (Normal Force N), Lực căng dây (Tension T) và Lực đẩy tên lửa (Thrust).","wordProblemCues":[{"phraseEn":"normal force (N)","meaningVi":"Phản lực vuông góc với mặt tiếp xúc","mathNotation":"N ⊥ surface"}],"commonTrapsVi":["⚠️ False Friend: \"Normal force\" = Phản lực PHÁP TUYẾN (vuông góc mặt tiếp xúc), không phải \"lực bình thường\"!"]},"keyEquations":[{"name":"normal force for a nonaccelerating horizontal surface","formula":"\\(\\mathbf{N} = m\\mathbf{g}\\)"},{"name":"tension for an object at rest","formula":"\\(\\mathbf{T} = m\\mathbf{g}\\)"}],"subsections":[{"uid":"hsphys.ch04.sec04.sub01","title":"Describing Newton’s Third Law of Motion","summaryVi":null,"paragraphs":["If you have ever stubbed your toe, you have noticed that although your toe initiates the impact, the surface that you stub it on exerts a force back on your toe. Although the first thought that crosses your mind is probably “ouch, that hurt” rather than “this is a great example of Newton’s third law,” both statements are true.","This is exactly what happens whenever one object exerts a force on another—each object experiences a force that is the same strength as the force acting on the other object but that acts in the opposite direction. Everyday experiences, such as stubbing a toe or throwing a ball, are all perfect examples of Newton’s third law in action.","Newton’s third law of motion states that whenever a first object exerts a force on a second object, the first object experiences a force equal in magnitude but opposite in direction to the force that it exerts.","Newton’s third law of motion tells us that forces always occur in pairs, and one object cannot exert a force on another without experiencing the same strength force in return. We sometimes refer to these force pairs as action-reaction pairs, where the force exerted is the action, and the force experienced in return is the reaction (although which is which depends on your point of view).","Newton’s third law is useful for figuring out which forces are external to a system. Recall that identifying external forces is important when setting up a problem, because the external forces must be added together to find the net force .","We can see Newton’s third law at work by looking at how people move about. Consider a swimmer pushing off from the side of a pool, as illustrated in [Figure 4.4]. She pushes against the pool wall with her feet and accelerates in the direction opposite to her push. The wall has thus exerted on the swimmer a force of equal magnitude but in the direction opposite that of her push. You might think that two forces of equal magnitude but that act in opposite directions would cancel, but they do not because they act on different systems.","In this case, there are two different systems that we could choose to investigate: the swimmer or the wall. If we choose the swimmer to be the system of interest, as in the figure, then \\({\\text{F}}_{\\text{wall on feet}}\\) is an external force on the swimmer and affects her motion. Because acceleration is in the same direction as the net external force , the swimmer moves in the direction of \\({\\text{F}}_{\\text{wall on feet}}.\\) Because the swimmer is our system (or object of interest) and not the wall, we do not need to consider the force \\({\\text{F}}_{\\text{feet on wall}}\\) because it originates from the swimmer rather than acting on the swimmer. Therefore, \\({\\text{F}}_{\\text{feet on wall}}\\) does not directly affect the motion of the system and does not cancel \\({\\text{F}}_{\\text{wall on feet}}.\\) Note that the swimmer pushes in the direction opposite to the direction in which she wants to move.","Other examples of Newton’s third law are easy to find. As a teacher paces in front of a whiteboard, he exerts a force backward on the floor. The floor exerts a reaction force in the forward direction on the teacher that causes him to accelerate forward. Similarly, a car accelerates because the ground pushes forward on the car's wheels in reaction to the car's wheels pushing backward on the ground. You can see evidence of the wheels pushing backward when tires spin on a gravel road and throw rocks backward.","Another example is the force of a baseball as it makes contact with the bat. Helicopters create lift by pushing air down, creating an upward reaction force. Birds fly by exerting force on air in the direction opposite that in which they wish to fly. For example, the wings of a bird force air downward and backward in order to get lift and move forward. An octopus propels itself forward in the water by ejecting water backward through a funnel in its body, which is similar to how a jet ski is propelled. In these examples, the octopus or jet ski push the water backward, and the water, in turn, pushes the octopus or jet ski forward."],"figures":[{"sourceId":"fs-idp78935376","filename":"CNX_HSPhysics_04_04_swimmer.jpg","relativePath":"media/CNX_HSPhysics_04_04_swimmer.jpg","alt":"A swimmer is underwater and is facing to the left. Her feet are on a wall and she is using her feet to get ready to push forward off the wall. She will accelerate in a direction opposite to the force of her feet pushing on the wall. This opposition is the result of Newton’s third law of motion, which dictates that the wall exerts a force on the swimmer that is equal in magnitude but that acts in the direction opposite to the force that the swimmer exerts on the wall. A free body diagram is shown to illustrate the force of the wall on the feet, the buoyancy force pushing upward on the girl, and the weight of the girl pushing downward."}],"tables":[]},{"uid":"hsphys.ch04.sec04.sub02","title":"Applying Newton’s Third Law","summaryVi":null,"paragraphs":["Forces are classified and given names based on their source, how they are transmitted, or their effects. In previous sections, we discussed the forces called push , weight , and friction . In this section, applying Newton’s third law of motion will allow us to explore three more forces: the normal force , tension , and thrust . However, because we haven’t yet covered vectors in depth, we’ll only consider one-dimensional situations in this chapter. Another chapter will consider forces acting in two dimensions. As we will see, we often apply the third law in conjunction with the second law in order to analyze the forces.","The gravitational force (or weight ) acts on objects at all times and everywhere on Earth. We know from Newton’s second law that a net force produces an acceleration; so, why is everything not in a constant state of freefall toward the center of Earth? The answer is the normal force. The normal force is the outward force that a surface applies to an object perpendicular to the surface, and it prevents the object from penetrating it. The normal force is a third law reaction force to the object’s force into the surface. In the case of an object at rest on a horizontal surface, it is the force needed to support the weight of that object. If an object on a flat surface is not accelerating, the net external force is zero and, as a consequence of Newton's second (not third!) law, the normal force has the same magnitude as the weight of the system but acts in the opposite direction. In equation form, we write that","Note that this equation is only true for a horizontal surface. This does not violate the third law since gravity and the normal force are not third law pairs.","The word tension comes from the Latin word meaning to stretch . Tension is the force along the length of a flexible connector, such as a string, rope, chain, or cable. Regardless of the type of connector attached to the object of interest, one must remember that the connector can only pull (or exert tension ) in the direction parallel to its length. Tension is a pull that acts parallel to the connector, and that acts in opposite directions at the two ends of the connector. This is possible because a flexible connector is simply a long series of action-reaction forces, except at the two ends where outside objects provide one member of the action-reaction forces.","Consider a person holding a mass on a rope, as shown in [Figure 4.4].","Tension in the rope must equal the weight of the supported mass, as we can prove by using Newton’s second law. If the 5.00 kg mass in the figure is stationary, then its acceleration is zero, so \\({\\mathbf{F}}_{\\text{net}} = 0.\\) The only external forces acting on the mass are its weight W and the tension T supplied by the rope. Summing the external forces to find the net force, we obtain","where T and W are the magnitudes of the tension and weight, respectively, and their signs indicate direction, with up being positive. By substituting m g for F net and rearranging the equation, the tension equals the weight of the supported mass, just as you would expect","For a 5.00-kg mass (neglecting the mass of the rope), we see that","Another example of Newton’s third law in action is thrust. Rockets move forward by expelling gas backward at a high velocity. This means that the rocket exerts a large force backward on the gas in the rocket combustion chamber, and the gas, in turn, exerts a large force forward on the rocket in response. This reaction force is called thrust ."],"figures":[{"sourceId":"fs-idp21617728","filename":"CNX_HSPhysics_04_04_rope.jpg","relativePath":"media/CNX_HSPhysics_04_04_rope.jpg","alt":"A hand is pulling downward on a rope with an object labeled m for mass attached to the bottom of the rope. A tension force vector from the hand points downward and another tension force vector from the object points upward. A weight force vector from the object points downward. The rope is the medium that transmits between the two objects' forces of equal magnitude but that act in opposite directions."}],"tables":[]},{"uid":"hsphys.ch04.sec04.sub03","title":"Performance Task","summaryVi":null,"paragraphs":["A car weighs 2,000 kg. It moves along a road by applying a force on the road with a parallel component of 560 N. There are two passengers in the car, each weighing 55 kg. If the magnitude of the drag experienced by the car is 45 N, what is the acceleration of the car?"],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch04.sec04.ex01","number":"4.4.1","title":"An Accelerating Equipment Cart","problem":"A physics teacher pushes a cart of demonstration equipment to a classroom, as in [Figure 4.4]. Her mass is 65.0 kg, the cart’s mass is 12.0 kg, and the equipment’s mass is 7.0 kg. To push the cart forward, the teacher’s foot applies a force of 150 N in the opposite direction (backward) on the floor. Calculate the acceleration produced by the teacher. The force of friction, which opposes the motion, is 24.0 N.","problemImages":[{"sourceId":"fs-idp63282816","filename":"CNX_HSPhysics_04_04_Teacher_img.jpg","relativePath":"media/CNX_HSPhysics_04_04_Teacher_img.jpg","alt":"A teacher is standing and facing to the right. She is pushing a cart with various items on it including books and boxes. The teacher and cart are labeled, \"System.\" A force vector labeled F teacher shows the force of the teacher's push on the cart and points to the right. A force vector of equal length labeled F cart show the force exerted by the cart and points to the left. A friction force vector at the bottom area of the cart points to the left. A force vector labeled F floor shows the force of the floor on the teacher's feet and points to the right. A force vector of equal length labeled F foot show the force exerted by teacher foot as she walks and points to the left. A free-body diagram of the system illustrates the friction force pointing to the left, the weight force pointing downward, the Newton force pointing upward, and the F floor force pointing to the right."}],"strategy":"Because they accelerate together, we define the system to be the teacher, the cart, and the equipment. The teacher pushes backward with a force \\({\\mathbf{F}}_{\\text{foot}}\\) of 150 N. According to Newton’s third law, the floor exerts a forward force \\({\\mathbf{F}}_{\\text{floor}}\\) of 150 N on the system. Because all motion is horizontal, we can assume that no net force acts in the vertical direction, and the problem becomes one dimensional. As noted in the figure, the friction f opposes the motion and therefore acts opposite the direction of \\({\\mathbf{F}}_{\\text{floor}}.\\)\nWe should not include the forces \\({\\mathbf{F}}_{\\text{teacher}}\\), \\({\\mathbf{F}}_{\\text{cart}}\\), or \\({\\mathbf{F}}_{\\text{foot}}\\) because these are exerted by the system, not on the system. We find the net external force by adding together the external forces acting on the system (see the free-body diagram in the figure) and then use Newton’s second law to find the acceleration.","solution":"Newton’s second law is\n\\(\\mathbf{a} = \\frac{{\\mathbf{F}}_{\\text{net}}}{m}\\text{.}\\) The net external force on the system is the sum of the external forces: the force of the floor acting on the teacher, cart, and equipment (in the horizontal direction) and the force of friction. Because friction acts in the opposite direction, we assign it a negative value. Thus, for the net force, we obtain\n\\({\\mathbf{F}}_{\\text{net}} = {\\mathbf{F}}_{\\text{floor}} - \\mathbf{f} = \\text{150 N} - \\text{24}\\text{.0 N} = \\text{126 N.}\\) The mass of the system is the sum of the mass of the teacher, cart, and equipment.\n\\(m\\text{= (65}\\text{.0 + 12}\\text{.0 + 7}\\text{.0) kg = 84 kg}\\) Insert these values of net F and m into Newton’s second law to obtain the acceleration of the system.\n\\(\\mathbf{a} = \\frac{{\\mathbf{F}}_{\\text{net}}}{m}a = \\frac{\\text{126 N}}{\\text{84 kg}} = \\text{1}{\\text{.5 m/s}}^{2}\\)\n\\({F}_{1} \\lt {F}_{2}\\)","solutionImages":[],"solutionTables":[],"discussion":"None of the forces between components of the system, such as between the teacher’s hands and the cart, contribute to the net external force because they are internal to the system. Another way to look at this is to note that the forces between components of a system cancel because they are equal in magnitude and opposite in direction. For example, the force exerted by the teacher on the cart is of equal magnitude but in the opposite direction of the force exerted by the cart on the teacher. In this case, both forces act on the same system, so they cancel. Defining the system was crucial to solving this problem."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch04.sec04.feat01","type":"tip","title":"Tips for Success","text":"A common misconception is that rockets propel themselves by pushing on the ground or on the air behind them. They actually work better in a vacuum, where they can expel exhaust gases more easily.","images":[]},{"uid":"hsphys.ch04.sec04.feat02","type":"physics-in-action","title":"Math: Problem-Solving Strategy for Newton’s Laws of Motion","text":"The basics of problem solving, presented earlier in this text, are followed here with specific strategies for applying Newton’s laws of motion. These techniques also reinforce concepts that are useful in many other areas of physics.\nFirst, identify the physical principles involved. If the problem involves forces, then Newton’s laws of motion are involved, and it is important to draw a careful sketch of the situation. An example of a sketch is shown in [Figure 4.4]. Next, as in [Figure 4.4], use vectors to represent all forces. Label the forces carefully, and make sure that their lengths are proportional to the magnitude of the forces and that the arrows point in the direction in which the forces act.\n(a) A sketch of Tarzan hanging motionless from a vine. (b) Arrows are used to represent all forces. T is the tension exerted on Tarzan by the vine, \\({\\mathbf{F}}_{\\text{T}}\\) is the force exerted on the vine by Tarzan, and W is Tarzan’s weight (i.e., the force exerted on Tarzan by Earth’s gravity). All other forces, such as a nudge of a breeze, are assumed to be negligible. (c) Suppose we are given Tarzan’s mass and asked to find the tension in the vine. We define the system of interest as shown and draw a free-body diagram, as shown in (d). \\({\\mathbf{F}}_{\\text{T}}\\) is no longer shown because it does not act on the system of interest; rather, \\({\\mathbf{F}}_{\\text{T}}\\) acts on the outside world. (d) The free-body diagram shows only the external forces acting on Tarzan. For these to sum to zero, we must have \\(\\mathbf{T} = \\mathbf{W}\\text{.}\\) Next, make a list of knowns and unknowns and assign variable names to the quantities given in the problem. Figure out which variables need to be calculated; these are the unknowns. Now carefully define the system: which objects are of interest for the problem. This decision is important, because Newton’s second law involves only external forces. Once the system is identified, it’s possible to see which forces are external and which are internal (see [Figure 4.4]).\nIf the system acts on an object outside the system, then you know that the outside object exerts a force of equal magnitude but in the opposite direction on the system.\nA diagram showing the system of interest and all the external forces acting on it is called a free-body diagram. Only external forces are shown on free-body diagrams, not acceleration or velocity. [Figure 4.4] shows a free-body diagram for the system of interest.\nAfter drawing a free-body diagram, apply Newton’s second law to solve the problem. This is done in [Figure 4.4] for the case of Tarzan hanging from a vine. When external forces are clearly identified in the free-body diagram, translate the forces into equation form and solve for the unknowns. Note that forces acting in opposite directions have opposite signs. By convention, forces acting downward or to the left are usually negative.\nIf a problem has more than one system of interest, more than one free-body diagram is required to describe the external forces acting on the different systems.\nTrue\nFalse","images":[{"sourceId":"fs-idp45179584","filename":"CNX_HSPhysics_04_04_Tarzan.jpg","relativePath":"media/CNX_HSPhysics_04_04_Tarzan.jpg","alt":"Four diagrams are shown: a, b, c, and d. Diagram a shows a sketch of Tarzan hanging motionless from a vine. Diagram b shows the same sketch as diagram a, but includes force vectors. A tension force vector points upward from Tarzan's hands to show tension exerted on Tarzan by the vine. Another tension force vector points downward from Tarzan's hands to show the force exerted on the vine by Tarzan. A weight force vector points from Tarzan downward to show the force exerted on Tarzan by Earth’s gravity. All other forces, such as a nudge of a breeze, are assumed to be negligible. Diagram c shows a system of interest in the event that Tarzan’s mass is known and we are asked to find the tension in the vine. This diagram shows the same sketch as diagram b, but it does not include the tension force vector downward from Tarzan's hands to show the force exerted on the vine by Tarzan because this force does not act on the system of interest. It only acts on the outside world. Diagram d shows a free-body diagram with only the external forces acting on Tarzan, with force T, tension, pointing upward and equal to force w, weight, pointing downward."}]}],"summaryPoints":["Newton’s third law of motion states that when one body exerts a force on a second body, the first body experiences a force that is equal in magnitude and opposite in direction to the force that it exerts.","When an object rests on a surface, the surface applies a force on the object that opposes the weight of the object. This force acts perpendicular to the surface and is called the normal force.","The pulling force that acts along a stretched flexible connector, such as a rope or cable, is called tension. When a rope supports the weight of an object at rest, the tension in the rope is equal to the weight of the object.","Thrust is a force that pushes an object forward in response to the backward ejection of mass by the object. Rockets and airplanes are pushed forward by thrust."],"glossary":[{"term":"Newton’s third law of motion","termVi":"Định luật III Newton","definition":"when one body exerts a force on a second body, the first body experiences a force that is equal in magnitude and opposite in direction to the force that it exerts","definitionVi":"Khi vật A tác dụng lên vật B một lực, vật B cũng tác dụng ngược lại vật A một lực cùng độ lớn, cùng giá, ngược chiều.","memoryTipVi":"Lực và phản lực đặt vào HAI VẬT KHÁC NHAU nên KHÔNG triệt tiêu nhau!"},{"term":"normal force","termVi":"Phản lực pháp tuyến (N)","definition":"that component of the contact force between two objects, which acts perpendicularly to and away from their plane of contact","definitionVi":"Lực nâng của bề mặt tiếp xúc tác dụng lên vật, luôn VUÔNG GÓC với bề mặt tiếp xúc.","memoryTipVi":"Trong toán–lý, \"Normal\" nghĩa là VUÔNG GÓC (perpendicular), không phải \"bình thường\"!"},{"term":"tension","termVi":"Lực căng dây (T)","definition":"a pulling force that acts along a connecting medium, especially a stretched flexible connector, such as a rope or cable; when a rope supports the weight of an object, the force exerted on the object by the rope is called tension","definitionVi":"Lực kéo truyền dọc theo sợi dây, cáp hoặc thanh mảnh bị kéo căng.","memoryTipVi":"Dây chỉ có thể KÉO, không bao giờ đẩy được."},{"term":"thrust","termVi":"Lực đẩy phản lực","definition":"a force that pushes an object forward in response to the backward ejection of mass by the object; rockets and airplanes are pushed forward by a thrust reaction force in response to ejecting gases backward","definitionVi":"Lực đẩy tên lửa/máy bay tiến lên phía trước do khí cháy phụt ra phía sau (Định luật III Newton).","memoryTipVi":"Ứng dụng trực tiếp của Định luật III Newton."}],"assessments":[{"uid":"hsphys.ch04.sec04.q001","sourceId":"fs-idp21612848","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What is Newtons third law of motion?","images":[],"choices":[{"label":"a","text":"Whenever a first body exerts a force on a second body, the first body experiences a force that is twice the magnitude and acts in the direction of the applied force."},{"label":"b","text":"Whenever a first body exerts a force on a second body, the first body experiences a force that is equal in magnitude and acts in the direction of the applied force."},{"label":"c","text":"Whenever a first body exerts a force on a second body, the first body experiences a force that is twice the magnitude but acts in the direction opposite the direction of the applied force."},{"label":"d","text":"Whenever a first body exerts a force on a second body, the first body experiences a force that is equal in magnitude but acts in the direction opposite the direction of the applied force."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q002","sourceId":"fs-idm26069024","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Considering Newtons third law, why dont two equal and opposite forces cancel out each other?","images":[],"choices":[{"label":"a","text":"Because the two forces act in the same direction"},{"label":"b","text":"Because the two forces have different magnitudes"},{"label":"c","text":"Because the two forces act on different systems"},{"label":"d","text":"Because the two forces act in perpendicular directions"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q003","sourceId":"fs-id1167065948876","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"What is the equation for the normal force for a body with mass m that is at rest on a horizontal surface?","images":[],"choices":[{"label":"a","text":"N = m"},{"label":"b","text":"N = mg"},{"label":"c","text":"N = mv"},{"label":"d","text":"N = g"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q004","sourceId":"fs-id1167065820624","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"An object with mass m is at rest on the floor. What is the magnitude and direction of the normal force acting on it?","images":[],"choices":[{"label":"a","text":"N = mv in upward direction"},{"label":"b","text":"N = mg in upward direction"},{"label":"c","text":"N = mv in downward direction"},{"label":"d","text":"N = mg in downward direction"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q006","sourceId":"eip-id1166849497742","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"True or FalseNewtons third law applies to the external forces acting on a system of interest.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q008","sourceId":"fs-idm8995088","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"True or False: A person accelerates while walking on the ground by exerting force F 1 . The ground in turn exerts force F 2 on the person. F 1 and F 2 are equal in magnitude but act in opposite directions. The person is able to accelerate because the two forces act on the different systems and the net force acting on the person is nonzero.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q009","sourceId":"eip-id1166849379874","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"A helicopter pushes air down, which, in turn, pushes the helicopter up. Which force affects the helicopters motion? Why?","images":[],"choices":[{"label":"a","text":"Air pushing upward affects the helicopters motion because it is an internal force that acts on the helicopter."},{"label":"b","text":"Air pushing upward affects the helicopters motion because it is an external force that acts on the helicopter."},{"label":"c","text":"The downward force applied by the blades of the helicopter affects its motion because it is an internal force that acts on the helicopter."},{"label":"d","text":"The downward force applied by the blades of the helicopter affects its motion because it is an external force that acts on the helicopter."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q010","sourceId":"fs-id1167065948876","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the equation for the normal force for a body with mass m that is at rest on a horizontal surface?","images":[],"choices":[{"label":"a","text":"N = m"},{"label":"b","text":"N = mg"},{"label":"c","text":"N = mv"},{"label":"d","text":"N = g"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q011","sourceId":"fs-id1167065820624","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"An object with mass m is at rest on the floor. What is the magnitude and direction of the normal force acting on it?","images":[],"choices":[{"label":"a","text":"N = mv in upward direction"},{"label":"b","text":"N = mg in upward direction"},{"label":"c","text":"N = mv in downward direction"},{"label":"d","text":"N = mg in downward direction"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q012","sourceId":"fs-idm28335728","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A person pushes an object of mass 5.0 kg along the floor by applying a force. If the object experiences a friction force of 10 N and accelerates at 18 m/s 2 , what is the magnitude of the force exerted by the person?","images":[],"choices":[{"label":"a","text":"-90 N"},{"label":"b","text":"-80 N"},{"label":"c","text":"90 N"},{"label":"d","text":"100 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q013","sourceId":"fs-idm12274624","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"One object exerts a force of magnitude F 1 on another object and experiences a force of magnitude F 2 in return. What is true for F 1 and F 2 ?","images":[],"choices":[{"label":"a","text":"F 1 > F 2"},{"label":"b","text":"F 1 < F 2"},{"label":"c","text":"F 1 = F 2"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q014","sourceId":"fs-idp29522944","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A weight is suspended with a rope and hangs freely. In what direction is the tension on the rope?","images":[],"choices":[{"label":"a","text":"parallel to the rope"},{"label":"b","text":"perpendicular to the rope"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q015","sourceId":"eip-id1166848667157","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A person weighing 55 kg walks by applying 160 N of force on the ground, while pushing a 10-kg object. If the person accelerates at 2 m/s 2 , what is the force of friction experienced by the system consisting of the person and the object?","images":[],"choices":[{"label":"a","text":"30 N"},{"label":"b","text":"50 N"},{"label":"c","text":"270 N"},{"label":"d","text":"290 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q016","sourceId":"eip-id1166851123845","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A 65-kg swimmer pushes on the pool wall and accelerates at 6 m/s 2 . The friction experienced by the swimmer is 100 N. What is the magnitude of the force that the swimmer applies on the wall?","images":[],"choices":[{"label":"a","text":"-490 N"},{"label":"b","text":"-290 N"},{"label":"c","text":"290 N"},{"label":"d","text":"490 N"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q017","sourceId":"fs-idm20350144","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A large truck with mass 30 m crashes into a small sedan with mass m . If the truck exerts a force F on the sedan, what force will the sedan exert on the truck?","images":[],"choices":[{"label":"a","text":"\\(\\frac{\\text{F}}{30}\\)"},{"label":"b","text":"F"},{"label":"c","text":"2F"},{"label":"d","text":"30F"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q018","sourceId":"fs-idm13418656","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"A fish pushes water backward with its fins. How does this propel the fish forward?","images":[],"choices":[{"label":"a","text":"The water exerts an internal force on the fish in the opposite direction, pushing the fish forward."},{"label":"b","text":"The water exerts an external force on the fish in the opposite direction, pushing the fish forward."},{"label":"c","text":"The water exerts an internal force on the fish in the same direction, pushing the fish forward."},{"label":"d","text":"The water exerts an external force on the fish in the same direction, pushing the fish forward."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q019","sourceId":"fs-idp54535024","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"True or FalseTension is the result of opposite forces in a connector, such as a string, rope, chain or cable, that pulls each point of the connector apart in the direction parallel to the length of the connector. At the ends of the connector, the tension pulls toward the center of the connector.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q020","sourceId":"fs-idp60758592","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"True or FalseNormal reaction is the force that opposes the force of gravity and acts in the direction of the force of gravity.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q021","sourceId":"fs-idm37243648","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"How do rockets propel themselves in space?","images":[],"choices":[{"label":"a","text":"Rockets expel gas in the forward direction at high velocity, and the gas, which provides an internal force, pushes the rockets forward."},{"label":"b","text":"Rockets expel gas in the forward direction at high velocity, and the gas, which provides an external force, pushes the rockets forward."},{"label":"c","text":"Rockets expel gas in the backward direction at high velocity, and the gas, which is an internal force, pushes the rockets forward."},{"label":"d","text":"Rockets expel gas in the backward direction at high velocity, and the gas, which provides an external force, pushes the rockets forward."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch04.sec04.q022","sourceId":"fs-idm27626080","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Are rockets more efficient in Earths atmosphere or in outer space? Why?","images":[],"choices":[{"label":"a","text":"Rockets are more efficient in Earths atmosphere than in outer space because the air in Earths atmosphere helps to provide thrust for the rocket, and Earth has more air friction than outer space."},{"label":"b","text":"Rockets are more efficient in Earths atmosphere than in outer space because the air in Earths atmosphere helps to provide thrust to the rocket, and Earth has less air friction than the outer space."},{"label":"c","text":"Rockets are more efficient in outer space than in Earths atmosphere because the air in Earths atmosphere does not provide thrust but does create more air friction than in outer space."},{"label":"d","text":"Rockets are more efficient in outer space than in Earths atmosphere because the air in Earths atmosphere does not provide thrust but does create less air friction than in outer space."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":2,"subsectionCount":3,"workedExampleCount":1,"snapLabCount":0,"glossaryCount":4,"assessmentCount":20}}],"summary":{"totalSections":5,"totalKeyEquations":6,"totalWorkedExamples":3,"totalSnapLabs":1,"totalGlossaryTerms":20,"totalAssessments":72,"referencedMediaCount":12},"qualityGate":{"passed":true,"checkedUids":91,"errors":[],"warnings":[]}};
